def para_text(el):
 p=el.get('paragraph')
 if not p: return ''
 return ''.join(e.get('textRun',{}).get('content','') for e in p.get('elements',[]))

def find_range(doc,marker='ANCHOR_TEXT'):
 body=doc.get('body',{}).get('content',[])
 for el in body:
  if marker in para_text(el):
   return el.get('startIndex'),el.get('endIndex')
 return None,None
